  if ($1 ~ /^[0-9]{1,2}$/ && $2 ~ /^[0-5][0-9]$/ && ($1+0) >= 0 && ($1+0) <= 23) {
    printf("%02d:%02d\n", $1+0, $2+0)
  } else { e++ }
}
END { if (!e) e=0; print e > "temp_workspace/errors.log" }' temp_workspace/timestamps.txt > temp_workspace/normalized_timestamps.txt
