Think: Coerce the trimmed normalized value into a canonical numeric string, write it to temp_check/canonical_numeric.txt, and log whether it changed to temp_check/coercion_log.txt.

Act: bash

```bash
awk -v cfile=temp_check/canonical_numeric.txt -v logfile=temp_check/coercion_log.txt '{
s=$0; t=s; gsub(/^[ \t]+/,"",t); gsub(/[ \t]+$/,"",t);
orig=t; num=t;
if (num ~ /^[+-]?([0-9]*)(\.[0-9]*)?([eE][+-]?[0-9]+)?$/) {
  # strip leading sign for processing, preserve negative sign
  sign="";
  if (substr(num,1,1) == "+") num = substr(num,2);
  else if (substr(num,1,1) == "-") { sign = "-"; num = substr(num,2); }
  intpart=""; fracpart=""; exp="";
  if (match(num,/^([0-9]*)(\.[0-9]*)?([eE][+-]?[0-9]+)?$/, m)) {
    intpart = m[1]; fracpart = m[2]; exp = m[3];
  }
  if (fracpart != "") fracpart = substr(fracpart,2); # drop dot
  if (intpart=="" && fracpart!="") intpart="0";
  gsub(/^0+/, "", intpart); if (intpart=="") intpart="0";
  if (fracpart != "") { gsub(/0+$/, "", fracpart); }
  expstr="";
  if (exp != "") {
    if (match(exp,/^[eE]([+-]?)([0-9]+)$/, em)) {
      esign = em[1]; enum = em[2];
      gsub(/^0+/, "", enum); if (enum=="") enum="0";
      if (esign == "-") expstr = "e-" enum; else expstr = "e" enum;
    }
  }
  if (fracpart != "") canonical = sign intpart "." fracpart expstr;
  else canonical = sign intpart expstr;
} else {
  canonical = orig;
}
print canonical > cfile;
changed = (canonical != orig) ? "yes" : "no";
print "original=[" orig "]\ncanonical=[" canonical "]\nchanged=" changed > logfile;
}' temp_check/normalized_var.txt
