 if ((getline line < file2) > 0) { split(line,a," "); c2=a[1] } close(file2)
 if(c1==c2) { print "Checksums: IDENTICAL" > out } else { print "Checksums: DIFFER" > out; print "matrix_copy checksum: " c1 >> out; print "matrix_normalized checksum: " c2 >> out }
 print "" >> out
 # read metadata into arrays
 delete m1; delete m2
